/**
 * SpreadToSinglePage.jsx
 * Converts a spreads document with multiple master pages into a single-page document
 * Preserves: margins, layout, element positioning, master page references
 * 
 * Author: Optimized for Adobe InDesign CS6+
 * Version: 2.0
 */

(function () {

    // ─────────────────────────────────────────────────────────────────
    // CONFIGURATION
    // ─────────────────────────────────────────────────────────────────
    var CONFIG = {
        progressInterval: 10,       // Update progress bar every N pages
        undoStepName: "Spread to Single Page Conversion",
        newDocSuffix: "_SinglePage",
        copyMasterItems: true,      // Copy master page items to document pages if overridden
        preserveLayerOrder: true,   // Maintain layer stack from source document
        verbose: false              // Set true for console debug output
    };

    // ─────────────────────────────────────────────────────────────────
    // ENTRY POINT
    // ─────────────────────────────────────────────────────────────────
    function main() {

        if (app.documents.length === 0) {
            alert("No document is open.\nPlease open a spreads document and try again.");
            return;
        }

        var srcDoc = app.activeDocument;

        if (!srcDoc.saved) {
            var saveDlg = confirm(
                "The document has not been saved.\n" +
                "It is strongly recommended to save before converting.\n\n" +
                "Continue without saving?"
            );
            if (!saveDlg) return;
        }

        // Confirm conversion
        var pageCount = srcDoc.pages.length;
        var spreadCount = srcDoc.spreads.length;

        var proceed = confirm(
            "SPREAD TO SINGLE PAGE CONVERTER\n\n" +
            "Source document: " + srcDoc.name + "\n" +
            "Spreads: " + spreadCount + "\n" +
            "Total pages: " + pageCount + "\n\n" +
            "This will create a NEW single-page document.\n" +
            "The original document will NOT be modified.\n\n" +
            "Proceed?"
        );
        if (!proceed) return;

        // Run with error handling
        try {
            app.scriptPreferences.userInteractionLevel = UserInteractionLevels.NEVER_INTERACT;
            var result = convertDocument(srcDoc);
            app.scriptPreferences.userInteractionLevel = UserInteractionLevels.INTERACT_WITH_ALL;

            if (result.success) {
                alert(
                    "✓ Conversion Complete!\n\n" +
                    "Pages converted: " + result.pagesConverted + "\n" +
                    "Master pages recreated: " + result.mastersRecreated + "\n" +
                    "Warnings: " + result.warnings.length +
                    (result.warnings.length > 0 ? "\n\n⚠ Warnings:\n" + result.warnings.join("\n") : "")
                );
            }
        } catch (e) {
            app.scriptPreferences.userInteractionLevel = UserInteractionLevels.INTERACT_WITH_ALL;
            alert("Error during conversion:\n" + e.message + "\nLine: " + e.line);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // MAIN CONVERSION FUNCTION
    // ─────────────────────────────────────────────────────────────────
    function convertDocument(srcDoc) {

        var result = {
            success: false,
            pagesConverted: 0,
            mastersRecreated: 0,
            warnings: []
        };

        // ── 1. Collect source document properties ──────────────────
        var srcPrefs        = srcDoc.documentPreferences;
        var srcMarginPrefs  = srcDoc.marginPreferences;
        var srcUnits        = srcDoc.viewPreferences;

        var pageWidth       = srcPrefs.pageWidth;
        var pageHeight      = srcPrefs.pageHeight;
        var facingPages     = srcPrefs.facingPages;
        var bleed           = getDocumentBleed(srcDoc);

        // ── 2. Build new document ──────────────────────────────────
        var newDoc = app.documents.add(false); // false = don't show window yet
        newDoc.viewPreferences.horizontalMeasurementUnits = srcUnits.horizontalMeasurementUnits;
        newDoc.viewPreferences.verticalMeasurementUnits   = srcUnits.verticalMeasurementUnits;

        // Document preferences – single page layout
        var newPrefs = newDoc.documentPreferences;
        newPrefs.facingPages            = false;   // ← Key: no facing pages
        newPrefs.pageWidth              = pageWidth;
        newPrefs.pageHeight             = pageHeight;
        newPrefs.pagesPerDocument       = pageCount(srcDoc);
        newPrefs.startPageNumber        = srcPrefs.startPageNumber;
        newPrefs.allowPageShuffle       = false;

        // Bleed & slug
        setDocumentBleed(newDoc, bleed);

        // ── 3. Sync layers ─────────────────────────────────────────
        if (CONFIG.preserveLayerOrder) {
            syncLayers(srcDoc, newDoc, result);
        }

        // ── 4. Recreate master pages ───────────────────────────────
        var masterMap = recreateMasterPages(srcDoc, newDoc, result);
        result.mastersRecreated = getObjectCount(masterMap);

        // ── 5. Convert document pages ─────────────────────────────
        convertDocumentPages(srcDoc, newDoc, masterMap, result);
        result.pagesConverted = newDoc.pages.length;

        // ── 6. Copy document-level settings ───────────────────────
        copyDocumentSettings(srcDoc, newDoc, result);

        // ── 7. Finalize ────────────────────────────────────────────
        var newName = buildNewDocName(srcDoc);
        newDoc.windows.add(); // Now show the document

        result.success = true;
        log("Conversion complete: " + newName);
        return result;
    }

    // ─────────────────────────────────────────────────────────────────
    // LAYER SYNCHRONIZATION
    // ─────────────────────────────────────────────────────────────────
    function syncLayers(srcDoc, newDoc, result) {
        // Remove default layers from new doc first
        var defaultLayer = newDoc.layers[0];

        // Create layers in REVERSE order (InDesign adds to top)
        var srcLayers = srcDoc.layers;

        for (var i = srcLayers.length - 1; i >= 0; i--) {
            var srcLayer = srcLayers[i];
            var newLayer;

            try {
                newLayer = newDoc.layers.itemByName(srcLayer.name);
                if (!newLayer.isValid) {
                    newLayer = newDoc.layers.add();
                }
            } catch (e) {
                newLayer = newDoc.layers.add();
            }

            newLayer.name              = srcLayer.name;
            newLayer.layerColor        = srcLayer.layerColor;
            newLayer.visible           = srcLayer.visible;
            newLayer.locked            = srcLayer.locked;
            newLayer.printable         = srcLayer.printable;
            newLayer.showGuides        = srcLayer.showGuides;
            newLayer.lockGuides        = srcLayer.lockGuides;
            newLayer.ignoreWrap        = srcLayer.ignoreWrap;

            try { newLayer.suppressPrint = srcLayer.suppressPrint; } catch (e) {}
        }

        // Remove the original default layer if it's now redundant
        try {
            if (defaultLayer.isValid && newDoc.layers.length > 1) {
                defaultLayer.remove(newDoc.layers[newDoc.layers.length - 1]);
            }
        } catch (e) {
            result.warnings.push("Could not remove default layer: " + e.message);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // MASTER PAGE RECREATION
    // ─────────────────────────────────────────────────────────────────
    function recreateMasterPages(srcDoc, newDoc, result) {

        // masterMap: { "srcMasterPrefix": "newMasterPrefix" }
        var masterMap = {};
        var srcMasters = srcDoc.masterSpreads;

        // First pass: create all master page shells
        // We need to handle parent master dependencies – sort by dependency
        var sortedMasters = sortMastersByDependency(srcMasters);

        for (var i = 0; i < sortedMasters.length; i++) {
            var srcMaster = sortedMasters[i];

            if (srcMaster.name === "None") {
                masterMap["None"] = "None";
                continue;
            }

            var newMaster = createSingleMasterPage(srcMaster, newDoc, masterMap, result);

            if (newMaster) {
                masterMap[srcMaster.namePrefix] = newMaster.namePrefix;
                log("Created master: " + srcMaster.name + " → " + newMaster.name);
            }
        }

        // Second pass: assign parent masters (basedOn relationships)
        assignMasterParents(srcMasters, newDoc, masterMap, result);

        return masterMap;
    }

    function createSingleMasterPage(srcMaster, newDoc, masterMap, result) {

        var srcPages = srcMaster.pages;

        // For each page in the source master spread, create one master in new doc
        for (var p = 0; p < srcPages.length; p++) {
            var srcPage = srcPages[p];

            var newMaster;
            var masterPrefix = generateMasterPrefix(srcMaster.namePrefix, p, srcPages.length);
            var masterName   = srcPages.length > 1
                ? srcMaster.baseName + (p === 0 ? "_L" : "_R")
                : srcMaster.baseName;

            // Add master page to new document
            try {
                newMaster = newDoc.masterSpreads.add({
                    namePrefix: masterPrefix,
                    baseName: masterName
                });
            } catch (e) {
                // Prefix conflict – generate a unique one
                masterPrefix = generateUniquePrefix(newDoc);
                newMaster = newDoc.masterSpreads.add({
                    namePrefix: masterPrefix,
                    baseName: masterName
                });
            }

            var newMasterPage = newMaster.pages[0];

            // Copy page geometry
            applyPageGeometry(srcPage, newMasterPage, newDoc);

            // Copy margin preferences
            applyMarginPreferences(srcPage, newMasterPage);

            // Copy column settings
            applyColumnSettings(srcPage, newMasterPage);

            // Copy all items from this master page
            copyPageItems(srcPage, newMasterPage, newDoc, masterMap, result, true);

            // Store page-level master reference
            newMaster._srcPrefix   = srcMaster.namePrefix;
            newMaster._srcPageIndex = p;

            return newMaster; // Return first one; loop handles multi-page spreads separately
        }
        return null;
    }

    function assignMasterParents(srcMasters, newDoc, masterMap, result) {
        for (var i = 0; i < srcMasters.length; i++) {
            var srcMaster = srcMasters[i];
            if (srcMaster.name === "None") continue;

            var basedOnMaster = null;
            try { basedOnMaster = srcMaster.basedOn; } catch (e) {}

            if (basedOnMaster && basedOnMaster.isValid && basedOnMaster.name !== "None") {
                var newPrefix    = masterMap[srcMaster.namePrefix];
                var parentPrefix = masterMap[basedOnMaster.namePrefix];

                if (newPrefix && parentPrefix) {
                    var newMaster    = newDoc.masterSpreads.itemByName(newPrefix + "-" + getMasterBaseName(newDoc, newPrefix));
                    var parentMaster = getMasterByPrefix(newDoc, parentPrefix);

                    try {
                        if (newMaster && newMaster.isValid && parentMaster && parentMaster.isValid) {
                            newMaster.basedOn = parentMaster;
                        }
                    } catch (e) {
                        result.warnings.push("Could not set master parent for: " + srcMaster.name);
                    }
                }
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // DOCUMENT PAGE CONVERSION
    // ─────────────────────────────────────────────────────────────────
    function convertDocumentPages(srcDoc, newDoc, masterMap, result) {

        var srcPages  = srcDoc.pages;
        var newPages  = newDoc.pages;

        // Ensure we have the right number of pages
        var neededPages = srcPages.length;
        var currentPages = newDoc.pages.length;

        if (currentPages < neededPages) {
            // Add pages without triggering master page application
            for (var a = currentPages; a < neededPages; a++) {
                newDoc.pages.add(LocationOptions.AT_END);
            }
        } else if (currentPages > neededPages) {
            for (var r = currentPages - 1; r >= neededPages; r--) {
                newDoc.pages[r].remove();
            }
        }

        // Process each page
        for (var i = 0; i < srcPages.length; i++) {
            var srcPage = srcPages[i];
            var newPage = newDoc.pages[i];

            // Apply geometry
            applyPageGeometry(srcPage, newPage, newDoc);

            // Apply margins
            applyMarginPreferences(srcPage, newPage);

            // Apply columns
            applyColumnSettings(srcPage, newPage);

            // Apply master page reference
            applyMasterToPage(srcPage, newPage, newDoc, masterMap, result);

            // Copy page items
            copyPageItems(srcPage, newPage, newDoc, masterMap, result, false);

            // Copy page label/name
            try { newPage.name = srcPage.name; } catch (e) {}

            // Copy color label
            try { newPage.colorLabel = srcPage.colorLabel; } catch (e) {}

            if (CONFIG.verbose) log("Converted page " + (i + 1) + "/" + srcPages.length);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // APPLY MASTER PAGE TO DOCUMENT PAGE
    // ─────────────────────────────────────────────────────────────────
    function applyMasterToPage(srcPage, newPage, newDoc, masterMap, result) {

        var srcMasterSpread = null;
        try { srcMasterSpread = srcPage.appliedMaster; } catch (e) {}

        if (!srcMasterSpread || srcMasterSpread.name === "None") {
            // Apply "None" master
            newPage.appliedMaster = newDoc.masterSpreads.firstItem();
            try { newPage.appliedMaster = NothingEnum.NOTHING; } catch (e) {}
            return;
        }

        var srcPrefix    = srcMasterSpread.namePrefix;
        var newPrefix    = masterMap[srcPrefix];

        if (!newPrefix) {
            result.warnings.push(
                "Master '" + srcMasterSpread.name + "' not found in master map for page " +
                (newPage.documentOffset + 1)
            );
            return;
        }

        var newMaster = getMasterByPrefix(newDoc, newPrefix);

        if (newMaster && newMaster.isValid) {
            try {
                newPage.appliedMaster = newMaster;
            } catch (e) {
                result.warnings.push("Could not apply master to page " + (newPage.documentOffset + 1) + ": " + e.message);
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // COPY PAGE ITEMS
    // ─────────────────────────────────────────────────────────────────
    function copyPageItems(srcPage, newPage, newDoc, masterMap, result, isMaster) {

        var items = srcPage.allPageItems;
